const copy={ru:{name:'Можно<br>говорить',nameInline:'Можно говорить ↗',aboutNav:'Об игре',tryNav:'Попробовать',rulesNav:'Как играть',apply:'Оставить заявку',eyebrow:'Карточки для настоящих разговоров',headline:'Не всё нужно<br>держать <span>в себе.</span>',lead:'Карточная игра для разговоров о том, что значит быть мужчиной. О чувствах, ожиданиях, отношениях и выборе быть собой.',openFirst:'Открыть первую карточку',players:'От 2 участников',noHost:'Без ведущего',sticker:'Меньше масок.<br>Больше тебя.',cardTag:'РАЗГОВОР НАЧИНАЕТСЯ С ТЕБЯ',heroHint:'Нажми на колоду, чтобы начать разговор',ticker1:'МОЖНО ЧУВСТВОВАТЬ',ticker2:'МОЖНО СОМНЕВАТЬСЯ',ticker3:'МОЖНО БЫТЬ СОБОЙ',demoLabel:'01 / Попробуй на ощупь',demoTitle:'Один вопрос.<br>Начало разговора.',demoIntro:'Выбери карточку. Переверни её.<br>Возможно, именно этот разговор давно ждал своего момента.',demoHint:'Нажми, чтобы перевернуть. Потяни, чтобы вращать. На телефоне включи «Вращать» под карточкой. С клавиатуры: Enter — переворот, стрелки — вращение, Escape — сброс.',next:'Следующий вопрос ↗',skip:'Пропустить',textMode:'Текстовый режим',hideText:'Скрыть список',flip:'Перевернуть',reset:'Сбросить поворот',rotate:'Вращать',done:'Готово',aboutLabel:'02 / Больше, чем игра',aboutTitle:'Быть собой —<br><span>тоже можно.</span>',aboutCopy:'Нас часто учат, каким должен быть мужчина. Реже спрашивают, как мы себя чувствуем и как наши поступки влияют на других. Эта колода приглашает поговорить об этом — с любопытством, уважением и готовностью слушать.',quote:'Можно чувствовать.<br>Можно просить поддержки.<br>Можно выбирать по-своему.',norms:'«Не плачь». «Всегда побеждай». «Не проси помощи». «Контролируй». Жёсткие ожидания могут мешать нам понимать себя и причинять боль окружающим. Разговор помогает замечать эти установки и искать другие способы действовать.',values:'Забота о себе идёт рядом с уважением к другим: гендерным равенством, правами женщин, уважением к разным идентичностям, отказом от насилия и ответственностью за свои поступки.',rulesLabel:'03 / Просто начните',rulesTitle:'Вытяни. Поделись.<br>Послушай.',ruleNote:'Здесь нет баллов, победителей и правильных ответов.',bigGroup:'Большая компания? Разделитесь на небольшие круги, чтобы у каждого было время высказаться.',agreement:'Сначала —<br>договоримся.',signupLabel:'Продолжим разговор?',signupTitle:'Хочешь узнать,<br>когда появится<br>колода?',signupCopy:'Оставь контакт — получи новости о выпуске и возможности попробовать игру.',formNote:'Демонстрационная форма. Отправка пока не подключена: введённые данные никуда не передаются и не сохраняются.',nameLabel:'Имя — необязательно',emailLabel:'Email',commentLabel:'Комментарий — необязательно',consent:'Согласен(-на) на обработку данных для получения новостей о колоде. Политика обработки данных будет добавлена перед запуском приёма заявок.',submit:'Хочу узнать о выпуске ↗',invalid:'Укажи корректный email, например name@example.com.',needConsent:'Отметь согласие, чтобы проверить форму.',demoStatus:'Форма заполнена корректно. Это демонстрация: заявка не отправлена. Введённые поля остаются на странице.',disclaimer:'Авторская концепция разговорной игры в контексте ценностей MenEngage. Вопросы и дизайн не являются официально утверждённым продуктом организации.',translationNote:'Казахская версия — черновой перевод, ожидающий редакторской проверки.',principles:'Принципы MenEngage ↗',pass:'Можно пропустить',questionWord:'Вопрос'},kk:{name:'Айтуға<br>болады',nameInline:'Айтуға болады ↗',aboutNav:'Ойын туралы',tryNav:'Байқап көру',rulesNav:'Қалай ойнаймыз',apply:'Өтінім қалдыру',eyebrow:'Шынайы әңгімеге арналған карталар',headline:'Бәрін іште<br>ұстау <span>міндет емес.</span>',lead:'Ер адам болу туралы әңгімеге арналған карта ойыны. Сезімдер, күтулер, қарым-қатынас және өзің болуды таңдау туралы.',openFirst:'Алғашқы картаны ашу',players:'2 қатысушыдан бастап',noHost:'Жүргізушісіз',sticker:'Бетперде аз.<br>Өзіңе жақын.',cardTag:'ӘҢГІМЕ СЕНЕН БАСТАЛАДЫ',heroHint:'Әңгімені бастау үшін колоданы бас',ticker1:'СЕЗІНУГЕ БОЛАДЫ',ticker2:'КҮМӘНДАНУҒА БОЛАДЫ',ticker3:'ӨЗІҢ БОЛУҒА БОЛАДЫ',demoLabel:'01 / Байқап көр',demoTitle:'Бір сұрақ.<br>Әңгіменің бастауы.',demoIntro:'Картаны таңда. Аударып көр.<br>Мүмкін, дәл осы әңгіменің уақыты келген шығар.',demoHint:'Аудару үшін бас. Айналдыру үшін сүйре. Телефонда картаның астындағы «Айналдыру» батырмасын қос. Пернетақта: Enter — аудару, бағыттауыштар — айналдыру, Escape — қалпына келтіру.',next:'Келесі сұрақ ↗',skip:'Өткізіп жіберу',textMode:'Мәтіндік режим',hideText:'Тізімді жасыру',flip:'Аудару',reset:'Бұрылысын қалпына келтіру',rotate:'Айналдыру',done:'Дайын',aboutLabel:'02 / Ойыннан да артық',aboutTitle:'Өзің болуға да<br><span>болады.</span>',aboutCopy:'Бізге ер адамның қандай болуы керегін жиі айтады. Ал не сезінетінімізді және іс-әрекетіміз өзгелерге қалай әсер ететінін сирек сұрайды. Бұл колода осыны қызығушылықпен, құрметпен және тыңдауға дайын болып талқылауға шақырады.',quote:'Сезінуге болады.<br>Қолдау сұрауға болады.<br>Өз жолыңды таңдауға болады.',norms:'«Жылама». «Әрқашан жең». «Көмек сұрама». «Бақылауда ұста». Қатаң күтулер өзімізді түсінуге кедергі болып, айналамыздағы адамдарға зиян келтіруі мүмкін. Әңгіме осы ұстанымдарды байқап, әрекет етудің басқа жолдарын табуға көмектеседі.',values:'Өзіңе қамқор болу өзгелерді құрметтеумен қатар жүреді: гендерлік теңдік, әйелдердің құқықтары, әртүрлі болмысты құрметтеу, зорлық-зомбылықтан бас тарту және өз іс-әрекетіңе жауапкершілік алу.',rulesLabel:'03 / Бастау оңай',rulesTitle:'Карта ал. Бөліс.<br>Тыңда.',ruleNote:'Мұнда ұпай, жеңімпаз және дұрыс жауап жоқ.',bigGroup:'Қатысушылар көп пе? Әркімнің сөйлеуге уақыты болуы үшін шағын топтарға бөлініңдер.',agreement:'Алдымен<br>келісіп алайық.',signupLabel:'Әңгімені жалғастырамыз ба?',signupTitle:'Колоданың қашан<br>шығатынын білгің<br>келе ме?',signupCopy:'Байланысыңды қалдыр — колоданың шығуы және ойынды байқап көру мүмкіндігі туралы жаңалық ал.',formNote:'Бұл — үлгі форма. Жіберу қызметі әлі қосылмаған: енгізілген деректер ешқайда жіберілмейді және сақталмайды.',nameLabel:'Аты-жөнің — міндетті емес',emailLabel:'Электрондық пошта',commentLabel:'Пікір — міндетті емес',consent:'Колода туралы жаңалық алу үшін деректерімді өңдеуге келісемін. Деректерді өңдеу саясаты өтінім қабылдау басталғанға дейін қосылады.',submit:'Шығарылым туралы білгім келеді ↗',invalid:'Дұрыс электрондық пошта мекенжайын енгіз, мысалы name@example.com.',needConsent:'Форманы тексеру үшін келісімді белгіле.',demoStatus:'Форма дұрыс толтырылды. Бұл — үлгі: өтінім жіберілген жоқ. Енгізілген мәліметтер бетте қалды.',disclaimer:'MenEngage құндылықтарына негізделген авторлық ойын тұжырымдамасы. Сұрақтар мен дизайн ұйым ресми түрде мақұлдаған өнім емес.',translationNote:'Қазақша нұсқа — редактор тексеруін күтетін аударма жобасы.',principles:'MenEngage қағидаттары ↗',pass:'Өткізіп жіберуге болады',questionWord:'Сұрақ'}};
const categories={ru:['Чувства и поддержка','Ожидания и стереотипы','Отношения и границы','Забота и равноправие','Ответственность и перемены'],kk:['Сезімдер мен қолдау','Күтулер мен таптаурындар','Қарым-қатынас пен шекаралар','Қамқорлық пен теңдік','Жауапкершілік пен өзгеріс']};
const questions={ru:['Какие слова поддержки тебе хотелось бы слышать чаще?','Как ты замечаешь, что тебе нужна пауза или помощь?','Как можно дать другу понять, что рядом с тобой можно говорить о чувствах?','Какое «мужчина должен» тебе хотелось бы поставить под вопрос?','Бывало ли, что ты отказывался от интересного занятия, потому что его считали «не мужским»? Можно ответить на вымышленном примере.','Какие качества ты ценишь в человеке независимо от его пола?','Где для тебя проходит граница между заботой и контролем?','Как можно отреагировать на чужое «нет», даже если ты расстроен?','Как спросить, комфортны ли человеку объятия, прикосновение или личный вопрос, не оказывая давления?','Какие повседневные дела заботы ты мог бы брать на себя без напоминания?','Что помогает распределять домашние обязанности справедливо?','Какую привычку заботиться о близких ты хотел бы перенять или создать сам?','Что можно сказать, если в компании прозвучала шутка, унижающая женщин или человека за его непохожесть?','Как выглядит извинение, после которого действительно меняется поведение?','Какую одну привычку в общении ты хотел бы изменить, чтобы рядом с тобой другим было спокойнее?'],kk:['Қандай қолдау сөздерін жиірек естігің келеді?','Үзіліс не көмек қажет екенін қалай байқайсың?','Досыңа сенімен сезімдері туралы еркін сөйлесе алатынын қалай білдіруге болады?','«Ер адам міндетті» деген қандай талапты қайта қарастырғың келеді?','Қызыққан ісіңнен оны «ерлерге тән емес» деп санағандықтан бас тартқан кезің болды ма? Ойдан шығарылған мысалмен жауап беруге болады.','Адамның жынысына қарамастан қандай қасиеттерін бағалайсың?','Сен үшін қамқорлық пен бақылаудың арасындағы шекара қай жерде?','Көңілің қалса да, өзгенің «жоқ» деген жауабын қалай қабылдауға болады?','Адамға қысым жасамай, құшақтау, қол тигізу немесе жеке сұрақ қою оған жайлы ма екенін қалай сұрауға болады?','Қандай күнделікті қамқорлық істерін еске салусыз өз мойныңа ала алар едің?','Үй шаруасын әділ бөлуге не көмектеседі?','Жақындарыңа қамқорлық жасаудың қандай әдетін үйренгің немесе қалыптастырғың келеді?','Ортада әйелдерді немесе өзгеше болғаны үшін біреуді кемсітетін әзіл айтылса, не деуге болады?','Мінез-құлықты шынымен өзгертетін кешірім сұрау қандай болады?','Жаныңда өзгелер өздерін жайлырақ сезінуі үшін қарым-қатынастағы қандай бір әдетіңді өзгерткің келеді?']};
const steps={ru:['Соберитесь от двух человек и договоритесь об уважительном разговоре.','По очереди вытягивайте карточку и читайте вопрос.','Отвечайте в том объёме, в котором вам комфортно. Остальные слушают.','Передавайте ход дальше. Любой вопрос можно пропустить.'],kk:['Екі не одан көп адам жиналып, құрметпен сөйлесуге келісіңдер.','Кезекпен карта алып, сұрақты оқыңдар.','Өзіңе жайлы көлемде жауап бер. Қалғандары тыңдайды.','Кезекті келесі адамға бер. Кез келген сұрақты өткізіп жіберуге болады.']};
const rules={ru:['Можно пропустить любой вопрос без объяснения.','Можно остановиться или сделать паузу.','Говорим от себя, не оцениваем чужой опыт.','Не требуем подробностей и не даём советов без запроса.','Не записываем и не распространяем чужие истории без разрешения.','Уважаем право каждого не соглашаться и говорить «нет».'],kk:['Кез келген сұрақты түсіндірместен өткізіп жіберуге болады.','Тоқтауға немесе үзіліс жасауға болады.','Өз атымыздан сөйлейміз, өзгенің тәжірибесін бағаламаймыз.','Егжей-тегжейін талап етпейміз, сұрамаса кеңес бермейміз.','Өзгенің әңгімесін рұқсатсыз жазып алмаймыз және таратпаймыз.','Әркімнің келіспеуге және «жоқ» деуге құқығын құрметтейміз.']};
let lang='ru';try{lang=localStorage.getItem('mg-language')==='kk'?'kk':'ru'}catch{}let indices=[0,3,6],active=0,textVisible=false,statusKey='';const states=Array.from({length:3},()=>({x:0,y:0,front:false,rotate:false}));const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function render(){document.documentElement.lang=lang;document.title=lang==='ru'?'Можно говорить — разговор начинается с тебя':'Айтуға болады — әңгіме сенен басталады';document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=copy[lang][e.dataset.t]);document.querySelectorAll('[data-lang]').forEach(e=>{e.classList.toggle('active',e.dataset.lang===lang);e.setAttribute('aria-pressed',e.dataset.lang===lang)});document.getElementById('hero-card').setAttribute('aria-label',copy[lang].openFirst);document.querySelector('.brand').setAttribute('aria-label',copy[lang].nameInline);document.getElementById('topics').innerHTML=categories[lang].map((c,i)=>'<div class="topic"><b>'+['♡','↗','↔','＋','✳'][i]+'</b>'+c+'</div>').join('');document.getElementById('steps').innerHTML=steps[lang].map((s,i)=>'<div class="step"><div class="num">0'+(i+1)+'</div><p>'+s+'</p></div>').join('');document.getElementById('agreements').innerHTML=rules[lang].map(r=>'<li>'+r+'</li>').join('');document.getElementById('text-list').innerHTML=questions[lang].map(q=>'<li>'+q+'</li>').join('');document.getElementById('text-mode').textContent=copy[lang][textVisible?'hideText':'textMode'];document.getElementById('status').textContent=statusKey?copy[lang][statusKey]:'';renderCards()}
function renderCards(){const host=document.getElementById('cards');host.innerHTML=indices.map((q,i)=>'<div class="card-slot"><div class="card-object" tabindex="0" role="button" data-card="'+i+'"><div class="face back"><div class="card-meta"><span>16+</span><span>'+String(q+1).padStart(2,'0')+'</span></div><div class="card-logo">'+copy[lang].name+'</div><div class="big-symbol">'+['(↗)','(＋)','(↔)'][i]+'</div><div class="card-bottom"><span>'+copy[lang].cardTag+'</span></div></div><div class="face front"><div class="category">'+categories[lang][Math.floor(q/3)]+'</div><div class="question"'+(questions[lang][q].length>125?' style="font-size:18px"':'')+'>'+questions[lang][q]+'</div><div class="card-bottom"><span>'+copy[lang].pass+'</span><span>'+String(q+1).padStart(2,'0')+'</span></div></div></div><div class="card-controls"><button data-flip="'+i+'">'+copy[lang].flip+'</button><button data-reset="'+i+'">'+copy[lang].reset+'</button><button data-rotate="'+i+'" aria-pressed="'+states[i].rotate+'">'+copy[lang][states[i].rotate?'done':'rotate']+'</button></div></div>').join('');host.querySelectorAll('[data-card]').forEach((el,i)=>{update(i);bindCard(el,i)});host.querySelectorAll('[data-flip]').forEach(b=>b.onclick=()=>flip(+b.dataset.flip));host.querySelectorAll('[data-reset]').forEach(b=>b.onclick=()=>reset(+b.dataset.reset));host.querySelectorAll('[data-rotate]').forEach(b=>b.onclick=()=>{const i=+b.dataset.rotate;states[i].rotate=!states[i].rotate;b.textContent=copy[lang][states[i].rotate?'done':'rotate'];b.setAttribute('aria-pressed',states[i].rotate);update(i)})}
function update(i){const s=states[i],el=document.querySelector('[data-card="'+i+'"]');el.style.transform='rotateX('+s.x+'deg) rotateY('+s.y+'deg)';el.style.touchAction=s.rotate?'none':'pan-y';el.classList.toggle('flat-front',s.front);el.classList.toggle('flat-back',!s.front);el.setAttribute('aria-label',s.front?questions[lang][indices[i]]:copy[lang].questionWord+' '+(indices[i]+1)+'. '+copy[lang].flip);el.querySelector('.back').setAttribute('aria-hidden',s.front);el.querySelector('.front').setAttribute('aria-hidden',!s.front)}
function flip(i){active=i;states[i].front=!states[i].front;states[i].x=0;states[i].y=states[i].front?180:0;update(i)}function reset(i){active=i;states[i].x=0;states[i].y=states[i].front?180:0;update(i)}
function bindCard(el,i){let start=null;el.onpointerdown=e=>{active=i;start={px:e.clientX,py:e.clientY,x:states[i].x,y:states[i].y,moved:false,allow:e.pointerType==='mouse'||states[i].rotate};if(start.allow){el.setPointerCapture(e.pointerId);el.classList.add('dragging')}};el.onpointermove=e=>{if(start){const dx=e.clientX-start.px,dy=e.clientY-start.py;if(Math.hypot(dx,dy)>7)start.moved=true;if(start.allow&&start.moved){states[i].x=start.x-dy*.8;states[i].y=start.y+dx*.8;update(i)}}else if(e.pointerType==='mouse'&&!states[i].front&&!reduced.matches){const r=el.getBoundingClientRect();el.style.transform='rotateX('+((.5-(e.clientY-r.top)/r.height)*10)+'deg) rotateY('+(((e.clientX-r.left)/r.width-.5)*12)+'deg)'}};el.onpointerup=e=>{if(!start)return;const click=!start.moved;start=null;el.classList.remove('dragging');if(el.hasPointerCapture(e.pointerId))el.releasePointerCapture(e.pointerId);if(click)flip(i)};el.onpointercancel=()=>{start=null;el.classList.remove('dragging')};el.onpointerleave=()=>{if(!start)update(i)};el.onkeydown=e=>{active=i;if(e.key==='Enter'||e.key===' '){e.preventDefault();flip(i)}else if(e.key==='Escape')reset(i);else if(e.key.startsWith('Arrow')){e.preventDefault();states[i].y+=e.key==='ArrowRight'?20:e.key==='ArrowLeft'?-20:0;states[i].x+=e.key==='ArrowUp'?20:e.key==='ArrowDown'?-20:0;update(i)}}}
function next(){indices[active]=(indices[active]+1)%15;states[active].front=true;reset(active);renderCards();document.querySelector('[data-card="'+active+'"]').focus({preventScroll:true})}document.getElementById('next').onclick=next;document.getElementById('skip').onclick=next;document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;try{localStorage.setItem('mg-language',lang)}catch{}render()});document.getElementById('text-mode').onclick=()=>{textVisible=!textVisible;document.getElementById('text-list').classList.toggle('hidden',!textVisible);document.getElementById('text-mode').textContent=copy[lang][textVisible?'hideText':'textMode'];document.getElementById('text-mode').setAttribute('aria-expanded',textVisible)};function openFirst(){states[0].front=true;reset(0);document.getElementById('try').scrollIntoView({behavior:reduced.matches?'instant':'smooth'})}document.getElementById('hero-card').onclick=openFirst;document.getElementById('open-first').onclick=openFirst;document.getElementById('form').onsubmit=e=>{e.preventDefault();const form=e.target,email=form.elements.email;if(!email.validity.valid){statusKey='invalid';email.setAttribute('aria-invalid','true');email.focus()}else if(!form.elements.consent.checked){email.removeAttribute('aria-invalid');statusKey='needConsent';form.elements.consent.focus()}else{email.removeAttribute('aria-invalid');statusKey='demoStatus'}document.getElementById('status').textContent=copy[lang][statusKey]};render();
